package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;
import java.time.Instant;

/**
 * 限发接口请求 DTO 集合；时间字段一律为 UTC 的 ISO-8601  instant。
 */
public final class Requests {

    private Requests() {
    }

    /**
     * 创建限发指令请求。
     *
     * @param unitId      目标机组编码
     * @param startUtc    限发区间起点（含），UTC
     * @param endUtc      限发区间终点（不含），UTC，左闭右开
     * @param maxPowerKw  区间内允许的最大平均功率，单位 kW
     */
    public record CreateDirectiveRequest(
            @NotBlank String unitId,
            @NotNull Instant startUtc,
            @NotNull Instant endUtc,
            @Positive int maxPowerKw) {
    }

    /**
     * 确认指令请求；requestId 幂等，同参重放返回原结果，异参返回 409。
     *
     * @param requestId   幂等请求标识
     * @param confirmedBy 确认人
     */
    public record ConfirmRequest(
            @NotBlank String requestId,
            @NotBlank String confirmedBy) {
    }

    /**
     * 上报 15 分钟平均功率采样；同一刻度重复上报视为迟到更正，追加新版本。
     *
     * @param tickUtc     采样刻度起点，UTC，须落在指令区间内并按 15 分钟对齐
     * @param avgPowerKw  该刻度内平均功率，单位 kW
     */
    public record ReadingRequest(
            @NotNull Instant tickUtc,
            @PositiveOrZero int avgPowerKw) {
    }

    /**
     * 对账请求；requestId 幂等，同参重放返回原结果，异参返回 409。
     *
     * @param requestId 幂等请求标识
     * @param auditor   对账人
     */
    public record ReconcileRequest(
            @NotBlank String requestId,
            @NotBlank String auditor) {
    }
}
'@, $enc)
[System.IO.File]::WriteAllText("$base\web\dto\Responses.java", @'
package com.example.starter.web.dto;

import com.example.starter.service.ReconcileIssue;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 限发接口响应 DTO 集合；时间字段一律为 UTC，电量单位 kWh，功率单位 kW。
 */
public final class Responses {

    private Responses() {
    }

    /**
     * 指令视图。
     *
     * @param directiveVersion 指令版本号，对账时固化
     * @param confirmedBy      确认人；未确认为 null
     * @param confirmedUtc     确认时间（UTC）；未确认为 null
     */
    public record DirectiveResponse(
            long id,
            String unitId,
            Instant startUtc,
            Instant endUtc,
            int maxPowerKw,
            String status,
            int directiveVersion,
            String confirmedBy,
            Instant confirmedUtc) {
    }

    /**
     * 采样视图（每刻度取最新版本）。
     */
    public record ReadingResponse(
            Instant tickUtc,
            int sampleVersion,
            int avgPowerKw,
            Instant reportedUtc) {
    }

    /**
     * 对账固化的单个采样刻度。
     */
    public record FrozenSampleView(
            Instant tickUtc,
            int sampleVersion,
            int avgPowerKw,
            BigDecimal energyKwh) {
    }

    /**
     * 对账单视图。
     *
     * @param reconVersion     同一指令内的对账版本
     * @param directiveVersion 固化的指令版本
     * @param totalEnergyKwh   累计电量，单位 kWh
     */
    public record ReconciliationResponse(
            long id,
            long directiveId,
            int reconVersion,
            int directiveVersion,
            String auditor,
            BigDecimal totalEnergyKwh,
            Instant createdUtc,
            List<FrozenSampleView> samples) {
    }

    /**
     * 差额链记录视图。
     */
    public record DifferenceResponse(
            long id,
            long reconciliationId,
            long previousReconciliationId,
            BigDecimal deltaKwh,
            Instant createdUtc) {
    }

    /**
     * 统一错误响应；对账拒绝时 issues 携带问题刻度，且不生成部分结果。
     */
    public record ErrorResponse(
            String message,
            List<ReconcileIssue> issues) {
    }
}
